   start??=now;const t=Math.min(1,(now-start)/6800),pose=tunnelPose(t,record.from,record.to),f=PraatpadWorld.fit($('pp-map').clientWidth,$('pp-map').clientHeight);
   host.anim.stepPoint=[pose.point[0]*f.scale+f.x,pose.point[1]*f.scale+f.y];
